INSERT INTO sys_config (config_name, config_key, config_value, config_type, remark)
VALUES ('邮件模板', 'mail_template', '<html><body><div style="position:relative;font-size:14px;padding:15px;line-height:1.7;"><div style="max-width:800px;padding-bottom:10px;margin:20px auto 0 auto;"><table cellpadding="0" cellspacing="0" style="background-color:#fff;border-collapse:collapse;border:1px solid #e5e5e5;box-shadow:0 10px 15px rgba(0,0,0,0.05);text-align:left;width:100%;font-size:14px;"><tbody><tr style="background-color:#f8f8f8;"><td><img style="padding:15px 0 15px 30px;width:50px" src="{siteLogo}" /><span>{siteName}</span></td></tr><tr><td style="padding:30px;"><h1 style="font-size:26px;font-weight:bold;color:#00785a;">验证您的邮箱地址</h1><p style="line-height:1.75em;">感谢您使用 {siteName}.</p><p style="line-height:1.75em;">以下是您的邮箱验证码，请将它输入到 <span style="color:#409eff;">{siteName}</span> 的邮箱验证码输入框中:</p></td></tr><tr><td style="padding:0 30px;"><p style="color:#253858;text-align:center;line-height:1.75em;background-color:#f2f2f2;min-width:200px;margin:0 auto;font-size:28px;border-radius:5px;border:1px solid #d9d9d9;font-weight:bold;">{code}</p></td></tr><tr><td style="padding:30px;"><p style="line-height:1.75em;">这一封邮件包括一些您的私密信息，请不要回复或转发它，以免带来不必要的信息泄露风险。</p></td></tr><tr><td style="padding:30px;"><hr><p style="text-align:center;line-height:1.75em;"><a href="{siteUrl}" style="text-decoration:none;color:#409eff">{siteName}</a></p></td></tr></tbody></table></div></div></body></html>', 'Y', '邮件HTML模板，支持 {siteName} {siteLogo} {siteUrl} {code} 占位符');
